<script setup lang="ts">
import { onMounted, onUnmounted, ref, shallowRef } from 'vue'
import { fetchClasses,fetchStudents,type RosterClass,type Student } from './records'
import { rosterFile,previewRoster,importRoster,saveStudent,type ImportCounts,type RosterImport,type StudentEdit } from './rosterManagement'
const emit=defineEmits<{changed:[]}>()
const classes=ref<RosterClass[]>([]),members=ref<Student[]>([]),selected=ref(''),busy=ref(false),error=ref(''),message=ref(''),uncertain=ref(false),file=shallowRef<File>(),defaultClass=ref(''),preview=shallowRef<ImportCounts>(),pending=shallowRef<RosterImport>(),consent=ref(false)
const add=ref<StudentEdit>({class_name:'',student_no:'',display_name:''}),edit=ref<StudentEdit>(),editConsent=ref(false)
let revision=0,alive=true
function resetImport(){preview.value=undefined;pending.value=undefined;consent.value=false}
async function read(){const token=++revision;busy.value=true;error.value='';members.value=[];edit.value=undefined;editConsent.value=false;uncertain.value=false;try{const all=await fetchClasses();const rows=selected.value?await fetchStudents(selected.value):[];if(!alive||revision!==token)return;classes.value=all;members.value=rows}catch(e){if(alive&&revision===token)error.value=(e as Error).message}finally{if(alive&&revision===token)busy.value=false}}
async function mutate(action:()=>Promise<unknown>,text:string){if(busy.value||uncertain.value)return;const token=revision;busy.value=true;error.value='';message.value='';try{await action();if(!alive||token!==revision)return;message.value=text;resetImport();edit.value=undefined;await read();if(alive)emit('changed')}catch{if(alive&&token===revision){uncertain.value=true;error.value='写入结果未能确认。请先刷新服务器名单核实，不会自动重复保存。'}}finally{if(alive)busy.value=false}}
async function prepare(){if(busy.value||!file.value||uncertain.value)return;const token=revision;busy.value=true;error.value='';resetImport();try{const payload=await rosterFile(file.value,defaultClass.value);const result=await previewRoster(payload);if(!alive||token!==revision)return;pending.value=payload;preview.value=result.preview}catch(e){if(alive&&token===revision)error.value=(e as Error).message}finally{if(alive&&token===revision)busy.value=false}}
function selectFile(event:Event){file.value=(event.target as HTMLInputElement).files?.[0];resetImport()}
function choose(s:Student){edit.value={student_id:s.student_id,student_no:s.student_no||'',display_name:s.display_name,enabled:!!s.enabled};editConsent.value=false}
onMounted(read);onUnmounted(()=>{alive=false;revision++;file.value=undefined;pending.value=undefined;edit.value=undefined;members.value=[]})
</script>
<template><section aria-label="花名册管理"><h3>花名册管理</h3><p>只修改名单资料；不重评分。已有学生ID及历史绑定保留，字段兼容行为由现有服务端决定。</p><button @click="read" :disabled="busy">刷新服务器名单</button><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
 <fieldset :disabled="busy||uncertain"><legend>导入名单</legend><label>花名册文件（CSV/TSV/XLSX）<input type="file" accept=".csv,.tsv,.xlsx" @change="selectFile"></label><label>默认班级（文件缺班级列时必填）<input v-model="defaultClass" @input="resetImport"></label><button @click="prepare" :disabled="!file">预览花名册导入</button>
  <template v-if="preview"><p>新增{{ preview.new_count }} · 已有{{ preview.existing_count }} · 重复码{{ preview.duplicate_count }} · 缺失/无效{{ preview.missing_count }} · 姓名冲突{{ preview.conflict_count }}</p><label class="check"><input type="checkbox" v-model="consent">我已核对预览，只新增有效记录，保留已有学生ID和历史归属</label><button @click="pending&&mutate(()=>importRoster(pending!),'名单导入已完成，请核对刷新后的班级。')" :disabled="!consent||!preview.new_count">确认导入名单</button></template>
 </fieldset>
 <form @submit.prevent="mutate(()=>saveStudent({...add}),'学生已新增；请刷新并选择该班级查看。')"><fieldset :disabled="busy||uncertain"><legend>新建班级并添加学生 / 向已有班级添加</legend><label>新增学生班级<input v-model="add.class_name" required maxlength="100"></label><label>新增学生学号（可选）<input v-model="add.student_no" maxlength="40"></label><label>新增学生姓名<input v-model="add.display_name" required maxlength="100"></label><button>保存新增学生</button></fieldset></form>
 <label for="manage-roster-class">编辑班级名单</label><select id="manage-roster-class" v-model="selected" @change="read" :disabled="busy"><option value="">请选择班级</option><option v-for="c in classes" :key="c.class_name">{{ c.class_name }}</option></select>
 <article v-for="s in members" :key="s.student_id" class="point-record"><p>{{ s.display_name }} · 学生ID {{ s.student_id }} · 学号 {{ s.student_no||'未录入' }} · 学号（可选） {{ s.student_no||'未录入' }} · {{ s.enabled?'启用':'停用' }}</p><button @click="choose(s)" :disabled="busy||uncertain">编辑{{ s.display_name }}</button></article>
 <form v-if="edit" @submit.prevent="editConsent&&mutate(()=>saveStudent({...edit!}),'学生记录已保存，历史归属及评分保留。')"><fieldset :disabled="busy||uncertain"><legend>修改学生资料</legend><label>修改学号（可选）<input v-model="edit.student_no" maxlength="40" @input="editConsent=false"></label><label>修改姓名<input v-model="edit.display_name" required maxlength="100" @input="editConsent=false"></label><label class="check"><input type="checkbox" v-model="edit.enabled" @change="editConsent=false">启用此学生</label><label class="check"><input type="checkbox" v-model="editConsent">确认更新这条学生记录，保持其学生ID和历史绑定</label><button :disabled="!editConsent">保存学生修改</button></fieldset></form>
</section></template>
